function enhanceActionButtons(scope=document){
 scope.querySelectorAll('button').forEach(btn=>{
  if(btn.dataset.iconEnhanced==='1'||btn.querySelector('svg'))return;
  const label=(btn.textContent||'').trim();
  const key=Object.keys(actionIconPaths).find(k=>label===k||label===k+' changes');
  if(!key)return;
  btn.title=btn.title||label;btn.setAttribute('aria-label',btn.getAttribute('aria-label')||label);
  btn.innerHTML=`<svg class="action-icon-svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${actionIconPaths[key]}</svg>`;
  btn.dataset.iconEnhanced='1';btn.classList.add('icon-action');
 });
}


function stopIdleTimer(){if(idleTimer)clearTimeout(idleTimer);idleTimer=null}
function resetIdleTimer(){if(!me)return;stopIdleTimer();idleTimer=setTimeout(async()=>{try{await fetch('/api/auth/logout',{method:'POST',headers:{'x-csrf-token':csrf}})}catch{}me=null;try{csrf=(await req('/csrf')).token}catch{}$('#headerNotifications')?.classList.add('hidden');showAuth('login');toast('You were signed out after five minutes of inactivity. Please sign in again.');},5*60*1000)}
['pointerdown','keydown','mousemove','touchstart','scroll'].forEach(event=>window.addEventListener(event,resetIdleTimer,{passive:true}));

const toast=(msg,ok=false)=>{const e=$('#toast');e.textContent=msg;e.className='alert'+(ok?' success':'');window.scrollTo({top:0,behavior:'smooth'})};
const req=async(url,method='GET',data)=>{const opts={method,headers:{}};if(method!=='GET'){opts.headers['x-csrf-token']=csrf;if(data instanceof FormData)opts.body=data;else{opts.headers['content-type']='application/json';opts.body=JSON.stringify(data||{})}}let r;try{r=await fetch('/api'+url,opts)}catch(networkError){throw Error('Cannot reach the HealthConnect server. Check your internet connection or wait for Render to finish starting, then try again.')}let out;try{out=await r.json()}catch(parseError){throw Error('The server returned an invalid response. Please refresh the page and try again.');}if(!r.ok)throw Error(out.error||'Request failed');return out};
