function departmentSpecialties(department){
 const d=String(department||'').toLowerCase();
 if(!d||/gopd|general outpatient/.test(d))return [...new Set([...specialtyCatalog.map(x=>x.name),...specialties.map(x=>x.name)])];
 const matched=specialtyCatalog.filter(x=>x.departments.some(k=>d.includes(k.toLowerCase())||k.toLowerCase().includes(d))).map(x=>x.name);
 const existing=specialties.map(x=>x.name).filter(n=>n.toLowerCase().includes(d)||d.includes(n.toLowerCase()));
 return [...new Set([...matched,...existing])];
}
function specialtyOptions(department,selected=''){
 const list=departmentSpecialties(department);
 if(selected&&!list.includes(selected))list.unshift(selected);
 return '<option value="">Select specialty</option><option value="Not applicable">Not applicable</option>'+list.map(n=>`<option value="${esc(n)}" ${selected===n?'selected':''}>${esc(n)}</option>`).join('');
}
function bindDepartmentSpecialty(formEl){
 const dep=formEl?.querySelector('[name=department]'),spec=formEl?.querySelector('[name=specialty]');if(!dep||!spec)return;
 const refresh=()=>{const selected=spec.value;spec.innerHTML=specialtyOptions(dep.value,selected);if(!spec.value)spec.value='';};
 dep.addEventListener('change',refresh);refresh();
}

function wireRank(form){const role=form.querySelector('[name=role]'),rank=form.querySelector('[name=rank]');if(!role||!rank)return;const refresh=()=>{const current=rank.value;rank.innerHTML='<option value="">Select rank</option>'+(rankOptions[role.value]||['Staff']).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');if([...rank.options].some(o=>o.value===current))rank.value=current};role.addEventListener('change',refresh);refresh()}

